package server_test

import (
	"embed"
	"os"
	"path/filepath"
	"testing"

	"github.com/pocketbase/pocketbase/core"
	"github.com/pocketbase/pocketbase/tests"
	"github.com/pocketbase/pocketbase/tools/archive"

	app "github.com/andreasmolnardev/taskboard/apps/server/internal/app"
	_ "github.com/andreasmolnardev/taskboard/apps/server/pb_migrations"
)

// The archive was generated by the Taskboard-era source at this immutable Git
// commit, using that source's PocketBase migrations and backup implementation.
const historicalTaskboardSourceCommit = "75b827a741f3ff537a226f57191f0be5006931cb"

//go:embed testdata/taskboard-75b827a-populated.zip
var historicalTaskboardFixture embed.FS

func TestHistoricalSourceBackupUpgradePreservesRecords(t *testing.T) {
	fixture, err := historicalTaskboardFixture.ReadFile("testdata/taskboard-75b827a-populated.zip")
	if err != nil {
		t.Fatal(err)
	}

	// Restore the archived historical database only into a fresh temporary
	// directory. The checked-in archive contains synthetic fixture records and
	// is never a copy of a developer's pb_data directory.
	restoreDir := t.TempDir()
	archivePath := filepath.Join(t.TempDir(), "taskboard-historical.zip")
	if err := os.WriteFile(archivePath, fixture, 0o600); err != nil {
		t.Fatal(err)
	}
	if err := archive.Extract(archivePath, restoreDir); err != nil {
		t.Fatalf("restore historical-source backup: %v", err)
	}
	if _, err := os.Stat(filepath.Join(restoreDir, "data.db")); err != nil {
		t.Fatalf("restored historical backup has no data.db: %v", err)
	}

	// NewTestApp clones the restored database before booting it, so PocketBase
	// migrations and current startup repairs run on an isolated disposable copy.
	currentApp, err := tests.NewTestApp(restoreDir)
	if err != nil {
		t.Fatalf("boot current Taskboard from historical-source backup (%s): %v", historicalTaskboardSourceCommit, err)
	}
	defer currentApp.Cleanup()

	// Re-run current migrations and repairs to exercise idempotency after the
	// historical DB has been opened by the current runtime.
	for range 2 {
		if err := currentApp.RunAppMigrations(); err != nil {
			t.Fatalf("run current app migrations: %v", err)
		}
		if err := app.EnsureCollections(currentApp); err != nil {
			t.Fatalf("repair current collections: %v", err)
		}
		if err := app.EnsureNotificationCollections(currentApp); err != nil {
			t.Fatalf("repair current notification collections: %v", err)
		}
		if err := app.EnsureCalDAVChanges(currentApp); err != nil {
			t.Fatalf("repair current CalDAV journal: %v", err)
		}
		if err := app.EnsureCardDAVChanges(currentApp); err != nil {
			t.Fatalf("repair current CardDAV journal: %v", err)
		}
	}

	assertHistoricalFixtureRecord(t, currentApp, "users", "histuser0000001", map[string]any{
		"email": "historical-taskboard@example.invalid",
	})
	assertHistoricalFixtureRecord(t, currentApp, "todos", "histtodo0000001", map[string]any{
		"owner":       "histuser0000001",
		"title":       "Historical task",
		"description": "Must survive the Slopstack runtime adoption",
		"completed":   false,
	})
	assertHistoricalFixtureRecord(t, currentApp, "events", "histevent000001", map[string]any{
		"owner": "histuser0000001",
		"title": "Historical event",
	})
	assertHistoricalFixtureRecord(t, currentApp, "contacts", "histcontact0001", map[string]any{
		"owner":          "histuser0000001",
		"address_book":   "fixture-address-book",
		"uid":            "fixture-contact-uid",
		"formatted_name": "Historical Contact",
		"email":          "historical-contact@example.invalid",
	})
}

func assertHistoricalFixtureRecord(t *testing.T, testApp core.App, collectionName, recordID string, fields map[string]any) {
	t.Helper()
	record, err := testApp.FindRecordById(collectionName, recordID)
	if err != nil {
		t.Fatalf("find historical %s record %s after upgrade: %v", collectionName, recordID, err)
	}
	if record.Id != recordID {
		t.Fatalf("historical %s record ID changed: got %q, want %q", collectionName, record.Id, recordID)
	}
	for field, want := range fields {
		if got := record.Get(field); got != want {
			t.Errorf("historical %s.%s = %#v, want %#v", collectionName, field, got, want)
		}
	}
}
